struct crypto_container {
        unsigned  id_pub;
        unsigned  id_prv;
        unsigned  id_cert;
};

struct container {
        char uuid[37];
        struct crypto_container exchange;
        struct crypto_container sign;

        struct container *next;
        struct container *prev;
};

struct container *Containers = NULL;

static struct {
        const char *name;
